# Let's verify by tracing through the BFS levels explicitly
def bfs_with_levels(graph, start):
    levels = {0: {start}}
    visited = {start}
    current_level = 0

    while True:
        next_level_nodes = set()
        for node in levels[current_level]:
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    next_level_nodes.add(neighbor)

        if not next_level_nodes:
            break

        current_level += 1
        levels[current_level] = next_level_nodes

    return levels

levels = bfs_with_levels(actual_graph, start_node)

print("BFS levels:")
for depth in sorted(levels.keys()):
    nodes = sorted(levels[depth])
    print(f"  Depth {depth}: {nodes} (count: {len(nodes)})")

print(f"\nNodes at exactly depth 4:")
print(sorted(levels.get(4, set())))
